#!/usr/bin/env bash
# Proves the k3s wrapper preserves network, registry, and supervisor contracts.

# shellcheck disable=SC2310,SC2312
set -euo pipefail

subject_directory="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
subject="${subject_directory}/k3s-entrypoint.sh"
registry_hosts_source="${subject_directory}/hosts.toml"
fail() {
  printf '%s\n' "$1" >&2
  exit 1
}

run_wrapper() {
  local fixture_root="$1"
  local route_interface="$2"
  local existing_address="$3"
  local fake_bin="${fixture_root}/bin"
  local fake_cgroup="${fixture_root}/cgroup"
  local fake_proc_sys="${fixture_root}/proc/sys"
  local registries_path="${fixture_root}/etc/rancher/k3s/registries.yaml"
  local true_binary
  true_binary="$(type -P true)"
  mkdir -p "${fake_bin}" "${fake_cgroup}" "${fake_proc_sys}/fs/inotify" \
    "$(dirname "${registries_path}")"
  printf '128\n' >"${fake_proc_sys}/fs/inotify/max_user_instances"
  printf '# File generated by k3s. DO NOT EDIT.\n' >"${registries_path}"

  cat >"${fake_bin}/ip" <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
printf '%s\n' "$*" >>"${TEST_IP_LOG}"
case "$*" in
  "-4 -o route show ${K3S_SHARED_IPV4_CIDR}")
    if [[ -n "${TEST_ROUTE_INTERFACE}" ]]; then
      printf '%s dev %s proto kernel scope link src 172.19.0.4\n' \
        "${K3S_SHARED_IPV4_CIDR}" "${TEST_ROUTE_INTERFACE}"
    fi
    ;;
  "-4 -o address show dev ${TEST_ROUTE_INTERFACE}")
    if [[ -n "${TEST_EXISTING_ADDRESS}" ]]; then
      printf '2: %s inet %s scope global %s\n' \
        "${TEST_ROUTE_INTERFACE}" "${TEST_EXISTING_ADDRESS}" \
        "${TEST_ROUTE_INTERFACE}"
    fi
    ;;
  "-4 address add ${K3S_NODE_IPV4_CIDR} dev ${TEST_ROUTE_INTERFACE}") ;;
  *) exit 64 ;;
esac
EOF
  cat >"${fake_bin}/k3s" <<'EOF'
#!/usr/bin/env bash
printf '%s\n' "$@" >"${TEST_K3S_LOG}"
EOF
  cat >"${fake_bin}/mdev" <<'EOF'
#!/usr/bin/env bash
printf '%s\n' "$*" >>"${TEST_MDEV_LOG}"
EOF
  cat >"${fake_bin}/mount" <<'EOF'
#!/usr/bin/env bash
if [[ "${TEST_FAIL_MOUNT}" == "true" ]]; then
  exit 32
fi
EOF
  chmod +x \
    "${fake_bin}/ip" \
    "${fake_bin}/k3s" \
    "${fake_bin}/mdev" \
    "${fake_bin}/mount"
  ln -sf "${true_binary}" "${fake_bin}/sleep"
  printf '%s\n' "${TEST_MOUNTINFO:-}" >"${fixture_root}/mountinfo"

  local -a env_args=(
    K3S_BINARY="${fake_bin}/k3s"
    K3S_CGROUP_ROOT="${fake_cgroup}"
    K3S_NODE_IPV4_CIDR="172.19.255.10/16"
    K3S_POD_IPV4_CIDR="10.240.0.0/16"
    K3S_SERVICE_IPV4_CIDR="172.31.0.0/20"
    K3S_SHARED_IPV4_CIDR="172.19.0.0/16"
    K3S_PROC_SYS_ROOT="${fake_proc_sys}"
    K3S_MOUNTINFO_PATH="${fixture_root}/mountinfo"
    K3S_REGISTRIES_PATH="${registries_path}"
    TEST_EXISTING_ADDRESS="${existing_address}"
    TEST_FAIL_MOUNT="${TEST_FAIL_MOUNT:-false}"
    TEST_IP_LOG="${fixture_root}/ip.log"
    TEST_K3S_LOG="${fixture_root}/k3s.log"
    TEST_MDEV_LOG="${fixture_root}/mdev.log"
    TEST_ROUTE_INTERFACE="${route_interface}"
    PATH="${fake_bin}:${PATH}"
  )

  local -a cmd_args=(server)
  if [[ $# -ge 4 ]]; then
    cmd_args+=("${@:4}")
  fi

  env "${env_args[@]}" sh "${subject}" "${cmd_args[@]}"
}

test_deduplicates_caller_cidr_flags() {
  local fixture_root
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN

  run_wrapper "${fixture_root}" eth7 "" \
    "--cluster-cidr=10.42.0.0/16" "--service-cidr=172.31.0.0/20"

  test "$(grep -Fxc -- '--cluster-cidr=10.240.0.0/16' "${fixture_root}/k3s.log" || true)" -eq 1 \
    || fail "wrapper did not retain the authoritative cluster CIDR exactly once"
  test "$(grep -Fxc -- '--service-cidr=172.31.0.0/20' "${fixture_root}/k3s.log" || true)" -eq 1 \
    || fail "wrapper did not retain the authoritative service CIDR exactly once"
  if grep -Fq -- '--cluster-cidr=10.42.0.0/16' "${fixture_root}/k3s.log"; then
    fail "wrapper leaked caller-provided cluster CIDR flag to k3s"
  fi
}

test_removes_floci_registry_mirror_before_k3s() {
  local fixture_root
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN

  run_wrapper "${fixture_root}" eth7 ""

  [[ ! -e "${fixture_root}/etc/rancher/k3s/registries.yaml" ]] \
    || fail "wrapper left Floci's headerless registry mirror active"
}

test_preserves_dragonfly_registry_header_contract() {
  grep -Fxq 'server = "http://origin-registry:5000/v2"' "${registry_hosts_source}" \
    || fail "registry hosts lost the native HTTP origin fallback"
  grep -Fxq '[host."http://127.0.0.1:4001"]' "${registry_hosts_source}" \
    || fail "registry hosts lost the Dragonfly proxy endpoint"
  grep -Fxq 'capabilities = ["pull", "resolve"]' "${registry_hosts_source}" \
    || fail "registry hosts lost the Dragonfly pull capabilities"
  grep -Fxq '[host."http://127.0.0.1:4001".header]' "${registry_hosts_source}" \
    || fail "registry hosts lost the Dragonfly header table"
  test "$(grep -Fxc 'X-Dragonfly-Registry = ["http://origin-registry:5000"]' "${registry_hosts_source}" || true)" -eq 1 \
    || fail "registry hosts must provide exactly one native HTTP origin header"
  if grep -Fq '[host."http://origin-registry:5000"]' "${registry_hosts_source}"; then
    fail "registry hosts must not add a headerless origin mirror"
  fi
}

test_raises_the_shared_inotify_instance_limit() {
  local fixture_root
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN

  run_wrapper "${fixture_root}" eth7 ""

  [[ "$(<"${fixture_root}/proc/sys/fs/inotify/max_user_instances")" == "1024" ]] \
    || fail "wrapper did not raise the shared inotify instance limit"
}

test_materializes_dynamic_loop_devices() {
  local fixture_root
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN

  run_wrapper "${fixture_root}" eth7 ""

  diff -u <(printf '%s\n' '-d' '-s') "${fixture_root}/mdev.log" \
    || fail "wrapper did not watch and scan for dynamic loop devices"
}

test_rejects_failed_csi_mount_propagation() {
  local fixture_root
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN

  if TEST_FAIL_MOUNT=true run_wrapper "${fixture_root}" eth7 ""; then
    fail "wrapper started k3s without CSI mount propagation"
  fi
  [[ ! -e "${fixture_root}/k3s.log" ]] \
    || fail "wrapper invoked k3s after CSI mount propagation failed"
}

test_enables_mutable_pv_node_affinity() {
  local fixture_root
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN

  run_wrapper "${fixture_root}" eth7 ""

  test "$(grep -Fxc -- '--kube-apiserver-arg=feature-gates=MutablePVNodeAffinity=true' "${fixture_root}/k3s.log" || true)" -eq 1 \
    || fail "wrapper did not enable mutable PV affinity in the API server"
  test "$(grep -Fxc -- '--kubelet-arg=feature-gates=MutablePVNodeAffinity=true' "${fixture_root}/k3s.log" || true)" -eq 1 \
    || fail "wrapper did not enable mutable PV affinity in kubelet"
}

test_disables_single_server_leader_election() {
  local fixture_root
  local flag
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN

  run_wrapper "${fixture_root}" eth7 ""

  for flag in \
    '--kube-cloud-controller-manager-arg=leader-elect=false' \
    '--kube-controller-manager-arg=leader-elect=false' \
    '--kube-scheduler-arg=leader-elect=false'; do
    test "$(grep -Fxc -- "${flag}" "${fixture_root}/k3s.log" || true)" -eq 1 \
      || fail "wrapper did not disable single-server leader election with ${flag}"
  done
}

test_disables_anonymous_auth() {
  local fixture_root
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN

  run_wrapper "${fixture_root}" eth7 ""

  test "$(grep -Fxc -- '--kube-apiserver-arg=anonymous-auth=false' "${fixture_root}/k3s.log" || true)" -eq 1 \
    || fail "wrapper did not disable kube-apiserver anonymous authentication"
}

test_enables_protect_kernel_defaults() {
  local fixture_root
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN

  run_wrapper "${fixture_root}" eth7 ""

  test "$(grep -Fxc -- '--protect-kernel-defaults=true' "${fixture_root}/k3s.log" || true)" -eq 1 \
    || fail "wrapper did not enable protect-kernel-defaults"
}

test_starts_without_cgroup_write_delegation() {
  local fixture_root
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN

  run_wrapper "${fixture_root}" eth7 ""

  [[ -e "${fixture_root}/k3s.log" ]] \
    || fail "wrapper required write access to its private cgroup"
  [[ -z "$(find "${fixture_root}/cgroup" -mindepth 1 -print -quit)" ]] \
    || fail "wrapper mutated its private cgroup fixture"
}

test_discovers_reassigned_interface() {
  local fixture_root
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN

  run_wrapper "${fixture_root}" eth7 ""

  grep -Fxq -- '-4 address add 172.19.255.10/16 dev eth7' "${fixture_root}/ip.log" \
    || fail "wrapper did not bind the durable address to the discovered interface"
  if grep -Fq -- 'route replace' "${fixture_root}/ip.log"; then
    fail "wrapper installed dead inter-cluster routes"
  fi
  grep -Fxq -- '--node-ip=172.19.255.10' "${fixture_root}/k3s.log" \
    || fail "wrapper did not publish the durable node IP"
  grep -Fxq -- '--flannel-iface=eth7' "${fixture_root}/k3s.log" \
    || fail "wrapper retained a fixed Docker interface"
  grep -Fxq -- '--kubelet-arg=fail-swap-on=true' "${fixture_root}/k3s.log" \
    || fail "wrapper did not keep pod swap disabled"
  grep -Fxq -- '--snapshotter=stargz' "${fixture_root}/k3s.log" \
    || fail "wrapper did not select k3s's built-in stargz snapshotter"
  if grep -Fq -- 'stargz-runtime' "${fixture_root}/k3s.log"; then
    fail "wrapper exposed the built-in snapshotter through custom node metadata"
  fi
  if grep -Fq -- 'image-service-endpoint' "${fixture_root}/k3s.log"; then
    fail "wrapper bypassed k3s's built-in stargz lifecycle"
  fi
  grep -Fxq -- "--kubelet-arg=eviction-minimum-reclaim=nodefs.available=2%,imagefs.available=2%" "${fixture_root}/k3s.log" \
    || fail "wrapper did not configure eviction minimum reclaim threshold"
  grep -Fxq -- '--kubelet-arg=image-gc-high-threshold=60' "${fixture_root}/k3s.log" \
    || fail "wrapper did not configure image garbage collection high threshold"
  grep -Fxq -- '--kubelet-arg=image-gc-low-threshold=40' "${fixture_root}/k3s.log" \
    || fail "wrapper did not configure image garbage collection low threshold"
}

test_keeps_existing_address() {
  local fixture_root
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN

  run_wrapper "${fixture_root}" eth9 "172.19.255.10/16"

  if grep -Fq -- 'address add' "${fixture_root}/ip.log"; then
    fail "wrapper added an address that was already present"
  fi
  grep -Fxq -- '--flannel-iface=eth9' "${fixture_root}/k3s.log" \
    || fail "wrapper did not use the restored shared-network interface"
}

test_rejects_missing_shared_route() {
  local fixture_root
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN

  if run_wrapper "${fixture_root}" "" "" >"${fixture_root}/stdout" 2>"${fixture_root}/stderr"; then
    fail "wrapper started k3s without the shared-network route"
  fi
  grep -Fq 'No interface routes the shared k3s network 172.19.0.0/16' "${fixture_root}/stderr" \
    || fail "wrapper did not explain the missing shared-network route"
  [[ ! -e "${fixture_root}/k3s.log" ]] || fail "wrapper invoked k3s after route discovery failed"
}

test_discovers_reassigned_interface
test_removes_floci_registry_mirror_before_k3s
test_preserves_dragonfly_registry_header_contract
test_raises_the_shared_inotify_instance_limit
test_materializes_dynamic_loop_devices
test_rejects_failed_csi_mount_propagation
test_enables_mutable_pv_node_affinity
test_disables_single_server_leader_election
test_disables_anonymous_auth
test_enables_protect_kernel_defaults
test_starts_without_cgroup_write_delegation
test_keeps_existing_address
test_rejects_missing_shared_route
test_deduplicates_caller_cidr_flags
